const POSITIONS = ['ST','ZOM','ZM','ZDM','LM','RM','LV','RV','IV','TW'];

function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;' }[c]));}
function formatMentions(v=''){
  const safe=esc(v);return safe.replace(/(^|[^A-Za-z0-9_.-])@([A-Za-z0-9_.-]{2,50})/g,(m,prefix,token)=>`${prefix}<a class="mention-link" data-link href="/mention/${encodeURIComponent(token.toLowerCase())}">@${token}</a>`);
}


function renderMentionResolver(token){return `<section class="container" style="padding-top:28px"><div class="panel" id="mentionResolveMount"><div class="empty"><strong>@${esc(token)}</strong><div style="margin-top:8px">Spieler oder Team wird gesucht…</div></div></div></section>`;}
async function hydrateMentionResolver(token){
  try{const r=await api(`/api/mentions/resolve?token=${encodeURIComponent(token)}`);const target=r.type==='club'?`/club/${r.slug}`:`/spieler/${r.slug}`;history.replaceState({},'',target);route();}
  catch(e){const m=document.querySelector('#mentionResolveMount');if(m)m.innerHTML=emptyCard('Mention nicht gefunden',`Für @${esc(token)} wurde kein Spieler oder Team gefunden.`);}
}
let mentionBox=null,mentionTimer=null;
function closeMentionBox(){mentionBox?.remove();mentionBox=null;}
function mentionQueryAtCursor(el){
  const pos=el.selectionStart??String(el.value||'').length,left=String(el.value||'').slice(0,pos),m=left.match(/(^|\s)@([A-Za-z0-9_.-]{0,40})$/);return m?{query:m[2],start:pos-m[2].length-1,end:pos}:null;
}
function positionMentionBox(el){
  if(!mentionBox)return;const r=el.getBoundingClientRect();mentionBox.style.left=`${Math.max(8,Math.min(window.innerWidth-328,r.left))}px`;mentionBox.style.top=`${Math.min(window.innerHeight-220,r.bottom+6)}px`;mentionBox.style.width=`${Math.min(320,Math.max(250,r.width))}px`;
}
async function showMentionSuggestions(el){
  const ctx=mentionQueryAtCursor(el);if(!ctx){closeMentionBox();return;}
  clearTimeout(mentionTimer);mentionTimer=setTimeout(async()=>{
    try{
      const r=await api(`/api/mentions?q=${encodeURIComponent(ctx.query)}`),items=r.items||[];closeMentionBox();if(!items.length)return;
      mentionBox=document.createElement('div');mentionBox.className='mention-suggest';mentionBox.innerHTML=`<div class="mention-suggest-head">Spieler & Teams markieren</div>${items.map(x=>`<button type="button" data-mention-insert="${esc(x.mention)}"><span class="mention-suggest-avatar"><img src="${assetUrl(x.avatar_key,x.type==='club'?demo.brand.defaultClub:demo.brand.defaultAvatar)}" alt=""></span><span><strong>${esc(x.label)}</strong><small>${x.type==='club'?'TEAM':'SPIELER'} · @${esc(x.mention)}</small></span></button>`).join('')}`;
      document.body.append(mentionBox);positionMentionBox(el);
      mentionBox.querySelectorAll('[data-mention-insert]').forEach(b=>b.addEventListener('mousedown',e=>{e.preventDefault();const fresh=mentionQueryAtCursor(el);if(!fresh)return;const token=b.dataset.mentionInsert;el.value=el.value.slice(0,fresh.start)+`@${token} `+el.value.slice(fresh.end);const cursor=fresh.start+token.length+2;el.focus();el.setSelectionRange(cursor,cursor);closeMentionBox();}));
    }catch{closeMentionBox();}
  },120);
}
function bindMentionInputs(root=document){
  root.querySelectorAll('textarea[name="body"],input[name="body"]').forEach(el=>{if(el.dataset.mentionBound)return;el.dataset.mentionBound='1';el.addEventListener('input',()=>showMentionSuggestions(el));el.addEventListener('keyup',e=>{if(e.key==='Escape')closeMentionBox();});el.addEventListener('blur',()=>setTimeout(closeMentionBox,180));});
}
