function fmt(n){return new Intl.NumberFormat('de-DE').format(Number(n||0));}
function euro(cents){return new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format((Number(cents)||0)/100);}
function marketEuro(v){const n=Number(v||0);if(n>=1000000)return `${(n/1000000).toFixed(n>=10000000?1:2).replace('.',',')} Mio. EPL €`;return `${fmt(Math.round(n/1000))}.000 EPL €`;}
function playerFrameUrl(player){if(Number(player?.use_totw_frame)&&Number(player?.totw_frame_active))return '/assets/totw/SpielerDerWocheRahmen.png';return player?.avatar_frame_asset_key?assetUrl(player.avatar_frame_asset_key,''):shopImageById(player?.equipped_avatar_frame_id);}
function path(){return location.pathname.replace(/\/$/,'') || '/';}
function navActive(href){const p=path(); return href==='/' ? p==='/' : p===href || p.startsWith(href+'/');}
function saveLocal(){localStorage.setItem('epl_following',JSON.stringify([...state.following]));}
function goto(url){history.pushState({},'',url); route(); window.scrollTo({top:0,behavior:'instant'});}
function toast(msg,type='ok'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;document.querySelector('#toast-root').append(el);setTimeout(()=>el.remove(),3200)}
function formatDateTime(v){if(!v) return '—'; const d=new Date(v); return `${String(d.getDate()).padStart(2,'0')}.${String(d.getMonth()+1).padStart(2,'0')}. ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function assetUrl(v,fallback){if(!v) return fallback; if(v.startsWith('http')||v.startsWith('/')) return v; return `/api/media/${v}`;}
function avatarFor(player){return assetUrl(player?.avatar_key || player?.avatar, demo.brand.defaultAvatar)}
function clubLogoFor(club){return assetUrl(club?.logo_key || club?.logo, demo.brand.defaultClub)}
function coverFor(obj){return assetUrl(obj?.cover_key || obj?.cover, demo.brand.defaultCover)}
function clubName(obj){return obj?.club || obj?.name || 'Unbekannter Club';}
function shopItemById(id){return state.shopCatalog.find(x=>Number(x.id)===Number(id))||demo.shop.find(x=>Number(x.id)===Number(id))||null;}
function shopImageById(id){const item=shopItemById(id);return assetUrl(item?.asset_key||item?.image,'');}
function safeStyleKey(v=''){return String(v||'').toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,40);}
function safeNameColor(v=''){const x=String(v||'').trim();return /^#[0-9a-f]{3,8}$/i.test(x)?x:'#eaf4ff';}
function nameStyleDescriptor(obj={}){
  const font=shopItemById(obj.equipped_name_font_id??obj.nameFont??null),fx=shopItemById(obj.equipped_name_effect_id??obj.nameEffect??null),color=shopItemById(obj.equipped_name_color_id??obj.nameColor??null);
  const classes=['epl-styled-name'];if(font?.style_key)classes.push(`epl-font-${safeStyleKey(font.style_key)}`);if(fx?.style_key)classes.push(`epl-fx-${safeStyleKey(fx.style_key)}`);
  return {classes:classes.join(' '),color:safeNameColor(color?.style_value||'#eaf4ff')};
}
function styledUsername(name,obj={}){const d=nameStyleDescriptor(obj);return `<span class="${d.classes}" style="--epl-name-color:${d.color}">${esc(name)}</span>`;}
function isProfileVerified(p){return !!(Number(p?.verified)||Number(p?.shop_verified));}
function nameStylePreview(item){
  const base={nameFont:state.equipped.nameFont,nameEffect:state.equipped.nameEffect,nameColor:state.equipped.nameColor};
  if(item?.item_type==='NAME_FONT')base.nameFont=item.id;if(item?.item_type==='NAME_EFFECT')base.nameEffect=item.id;if(item?.item_type==='NAME_COLOR')base.nameColor=item.id;
  return styledUsername(state.me?.username||'DEIN NAME',base);
}
function pageMeta(key,defaults={}){return state.cms.pages.find(x=>x.page_key===key)||defaults;}
function cmsBlocks(key){return (state.cms.blocks||[]).filter(x=>x.page_key===key);}
function cmsText(pageKey,contentKey,fallback=''){const e=(state.cms.entries||[]).find(x=>x.page_key===pageKey&&x.content_key===contentKey);return e?.value??fallback;}
function renderCmsBlocks(key){const blocks=cmsBlocks(key);if(!blocks.length)return '';return `<section class="container cms-public-blocks">${blocks.map(b=>`<article class="panel cms-public-block ${state.editMode?'inline-editable':''}" ${state.editMode?`data-inline-block="${b.id}"`:''}>${b.image_key?`<img src="${assetUrl(b.image_key,'')}" alt="">`:''}<div><h2>${esc(b.title)}</h2><p>${esc(b.body||'').replace(/\n/g,'<br>')}</p>${b.cta_label&&b.cta_href?`<a class="btn btn-primary" data-link href="${esc(b.cta_href)}">${esc(b.cta_label)}</a>`:''}</div>${state.editMode?'<span class="inline-edit-chip">✎ BLOCK</span>':''}</article>`).join('')}</section>`;}
function canModerateViewer(){return !!(state.me&&(state.me.role==='SUPER_ADMIN'||(state.me.admin_roles||[]).some(r=>r==='FULL_ADMIN'||r==='USER_ADMIN')));}
function onlineDot(online){return `<span class="presence-dot ${Number(online)?'online':'offline'}" title="${Number(online)?'Online':'Offline'}"></span>`;}
function socialHref(kind,value=''){
  const v=String(value||'').trim();if(!v)return '';
  if(/^https:\/\//i.test(v))return v;
  if(kind==='discord')return /^discord\.gg\//i.test(v)?`https://${v}`:'';
  const handle=v.replace(/^@/,'').replace(/^https?:\/\/[^/]+\//i,'').replace(/\/$/,'');
  if(!handle)return '';
  if(kind==='tiktok')return `https://www.tiktok.com/@${encodeURIComponent(handle)}`;
  if(kind==='twitch')return `https://www.twitch.tv/${encodeURIComponent(handle)}`;
  return '';
}
function profileSocialLinks(obj={}){
  const links=[['discord','Discord',socialHref('discord',obj.discord)],['tiktok','TikTok',socialHref('tiktok',obj.tiktok)],['twitch','Twitch',socialHref('twitch',obj.twitch)]];
  return links.some(x=>x[2])?`<div class="profile-social-links">${links.filter(x=>x[2]).map(([icon,label,href])=>`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer" title="${label}"><img src="/assets/social/${icon}.svg" alt="${label}"><span>${label}</span></a>`).join('')}</div>`:'';
}
function authorImage(post){return assetUrl(post?.author_image_key,post?.author_type==='club'?demo.brand.defaultClub:demo.brand.defaultAvatar);}
function emptyCard(title,text){return `<div class="empty"><strong>${title}</strong><div style="margin-top:8px">${text}</div></div>`;}
function consumeOAuthNotice(){
  const params=new URLSearchParams(location.search),message=params.get('oauth_error');
  if(!message)return;
  toast(message,'error');
  history.replaceState({},'',location.pathname);
}

async function api(url, options={}){
  const headers = { ...(options.headers||{}) };
  if (!(options.body instanceof FormData) && !headers['Content-Type']) headers['Content-Type']='application/json';
  const res = await fetch(url,{credentials:'include',...options,headers});
  const data = await res.json().catch(()=>({}));
  if(!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
  return data;
}

async function bootstrap(){
  try { state.config = await api('/api/config'); } catch {}
  try { state.me = (await api('/api/auth/me')).user; } catch {}
  await Promise.all([refreshCms(),refreshShopCatalog()]);
  await refreshPublicData();
  if(state.me){
    await Promise.all([refreshSocialState(),refreshInventory(),refreshSocialFeed(),refreshGoals(),refreshNotifications(),refreshContracts()]);
    startPresence();
  }
  route();
  consumeOAuthNotice();
}
async function refreshPublicData(){
  try{
    const [boot,players,clubs,table]=await Promise.all([api('/api/bootstrap'),api('/api/players'),api('/api/clubs'),api('/api/standings')]);
    state.live.news = boot.news || [];
    state.live.fixtures = boot.fixtures || [];
    state.live.standings = table.standings || boot.standings || [];
    state.live.divisions = table.divisions || [];
    state.live.season = table.season || null;
    state.live.players = players.players || boot.players || [];
    state.live.clubs = clubs.clubs || boot.clubs || [];
    state.live.transfers = boot.transfers || [];
    state.live.recentUsers = boot.recentUsers || [];
  }catch{}
}
async function refreshSocialState(){
  if(!state.me)return;
  try{const r=await api('/api/social/state');state.following=new Set(r.following||[]);saveLocal();}catch{}
}
async function refreshInventory(){
  if(!state.me){state.inventory=[];state.owned=new Set();return;}
  try{const r=await api('/api/inventory');state.inventory=r.items||[];state.equipped=r.equipped||{avatarFrame:null,coverFrame:null,nameFont:null,nameEffect:null,nameColor:null,badge:null};state.totw=r.totw||{available:false,equipped:false,assetKey:'/assets/totw/SpielerDerWocheRahmen.png'};state.owned=new Set(state.inventory.map(x=>String(x.id)));}catch{}
}
async function refreshSocialFeed(){
  if(!state.me){state.socialFeed=[];return;}
  try{state.socialFeed=(await api('/api/social/feed')).posts||[];}catch{state.socialFeed=[];}
}
async function refreshShopCatalog(){try{const r=await api('/api/shop/catalog');state.shopCatalog=r.items||[];state.shopMeta={managedClub:r.managedClub||null,teamEntitlements:r.teamEntitlements||null};}catch{state.shopCatalog=[...demo.shop];state.shopMeta={managedClub:null,teamEntitlements:null};}}
async function refreshCms(){try{state.cms=await api('/api/cms/public');}catch{state.cms={pages:[],slides:[],blocks:[],entries:[]};}}
async function refreshGoals(){if(!state.me){state.goals=null;return;}try{state.goals=await api('/api/goals');}catch{state.goals=null;}}
async function refreshNotifications(){if(!state.me){state.notifications=[];state.notificationUnread=0;return;}try{const r=await api('/api/notifications');state.notifications=r.notifications||[];state.notificationUnread=Number(r.unread||0);}catch{state.notifications=[];state.notificationUnread=0;}}
async function refreshContracts(){if(!state.me){state.contracts=[];return;}try{state.contracts=(await api('/api/contracts/mine')).contracts||[];}catch{state.contracts=[];}}
function startPresence(){
  if(state.presenceTimer)clearInterval(state.presenceTimer);
  const ping=async()=>{try{await api('/api/presence',{method:'POST',body:'{}'});}catch{}};
  ping();
  // Presence only: one request every five minutes. No activity coin rewards.
  state.presenceTimer=setInterval(ping,300000);
}

window.addEventListener('popstate',route);
document.addEventListener('click',e=>{const a=e.target.closest('a[data-link]'); if(a){e.preventDefault();goto(a.getAttribute('href'));}});

function layout(content){
  const nav=[['/','Home'],['/news','News'],['/liga','Liga'],['/tabelle','Tabelle'],['/teams','Teams'],['/spieler','Spieler'],['/transfers','Transfers'],['/shop','Shop'],['/regeln','Regeln']];
  const fullEditor=!!(state.me&&(state.me.role==='SUPER_ADMIN'||(state.me.admin_roles||[]).includes('FULL_ADMIN')));
  return `<div class="shell ${state.editMode?'edit-mode-active':''}">
    <header class="site-header"><div class="container header-inner">
      <a href="/" data-link class="brand"><img src="${demo.brand.logo}" alt="${esc(demo.brand.name)}"></a>
      <nav class="nav">${nav.map(([h,l])=>`<a data-link class="nav-link ${navActive(h)?'active':''}" href="${h}">${l}</a>`).join('')}</nav>
      <button class="mobile-toggle" id="mobileMenu" aria-label="Menü öffnen">${mobileIcon('menu')}</button>
      <div class="header-actions">${state.me?`${state.me.managed_club_slug?'<a class="login-link control-link" data-link href="/manager">VM PANEL</a>':''}${state.me.is_admin||state.me.role==='SUPER_ADMIN'?'<a class="login-link control-link" data-link href="/admin">ADMIN</a>':''}${fullEditor?`<button class="header-icon-action edit-mode-toggle ${state.editMode?'active':''}" data-edit-mode-toggle title="${state.editMode?'Edit Mode beenden':'Edit Mode starten'}">${mobileIcon('edit')}<small>EDIT</small></button>`:''}<a class="header-icon-action notification-link" data-link href="/benachrichtigungen" title="Benachrichtigungen">${mobileIcon('bell')}<b class="notification-badge" data-notification-badge ${state.notificationUnread?'':'hidden'}>${fmt(state.notificationUnread)}</b></a><a class="header-icon-action" data-link href="/nachrichten" title="Nachrichten">${mobileIcon('chat')}</a><a class="header-profile-action" data-link href="/spieler/${esc(state.me.username.toLowerCase())}" title="Profil">${mobileIcon('profile')}<small>${esc(state.me.username)}</small></a><button class="btn btn-primary logout-compact" data-action="logout">ABMELDEN</button>`:`<a class="btn btn-primary" data-link href="/registrieren">♙ REGISTRIEREN</a><a class="login-link" data-link href="/login">👤 Login</a>`}</div>
    </div></header>${mobileDrawer()}
    ${state.editMode?'<div class="edit-mode-banner"><b>EDIT MODE</b><span>Klicke auf markierte Texte/Bilder, um sie direkt zu bearbeiten.</span><button data-edit-mode-toggle>BEENDEN</button></div>':''}
    <main class="page">${content}</main>${footer()}${mobileBottomNav()}</div>`;
}
function footer(){const socials=[['discord','Discord','#'],['x','X','#'],['instagram','Instagram','#'],['youtube','YouTube','#'],['tiktok','TikTok','#']];return `<footer class="site-footer"><div class="container footer-inner"><div class="socials"><span>FOLGE UNS</span>${socials.map(([icon,label,href])=>`<a class="social-logo-link" href="${href}" aria-label="${label}"><img src="/assets/social/${icon}.svg" alt="${label}"></a>`).join('')}</div><div class="footer-brand"><img class="footer-epl-logo" src="${demo.brand.logo}" alt="EPL"><span>${esc(cmsText('site','footer_tagline','ELITE PRO LEAGUE – COMPETE. CONNECT. CONQUER.'))}</span></div><div class="footer-links"><a href="/regeln" data-link>Impressum</a><a href="/regeln" data-link>Datenschutz</a><a href="/regeln" data-link>AGB</a><a href="/regeln" data-link>Kontakt</a></div></div></footer>`}


function mobileDrawer(){
  const link=(href,icon,label,extra='')=>`<a data-link href="${href}" class="mobile-drawer-link">${mobileIcon(icon)}<span>${label}</span>${extra}</a>`;
  const head=`<div class="mobile-drawer-head"><div><small>EPL</small><strong>Navigation</strong></div><button type="button" data-mobile-close aria-label="Menü schließen">${mobileIcon('close')}</button></div>`;
  if(!state.me)return `<div class="mobile-drawer" id="mobileDrawer">${head}${link('/news','news','News')}${link('/tabelle','table','Tabelle')}${link('/transfers','transfers','Transfers')}${link('/shop','shop','Shop')}${link('/regeln','rules','Regeln')}${link('/login','profile','Login')}</div>`;
  return `<div class="mobile-drawer" id="mobileDrawer">${head}
    ${link('/news','news','News')}${link('/tabelle','table','Tabelle')}${link('/transfers','transfers','Transfers')}${link('/shop','shop','Shop')}${link('/regeln','rules','Regeln')}
    <div class="mobile-drawer-separator"></div>
    ${link('/hub','hub','Mein Daily Hub')}${link(`/spieler/${esc(state.me.username.toLowerCase())}`,'profile','Mein Profil')}${link('/benachrichtigungen','bell','Benachrichtigungen',state.notificationUnread?`<b class="drawer-badge">${fmt(state.notificationUnread)}</b>`:'')}${link('/nachrichten','chat','Nachrichten')}
    ${state.me.managed_club_slug?link('/manager','manager','VM Panel'):''}${state.me.is_admin||state.me.role==='SUPER_ADMIN'?link('/admin','admin','Admin'):''}
    <button class="mobile-drawer-logout" data-action="logout">${mobileIcon('logout')}<span>Abmelden</span></button>
  </div>`;
}

function mobileBottomNav(){
  const items=[['/','home','Home'],['/liga','league','Liga'],['/teams','teams','Teams'],['/spieler','player','Spieler'],[state.me?'/nachrichten':'/login','chat','Chats']];
  return `<nav class="mobile-app-nav">${items.map(([h,i,l])=>`<a data-link href="${h}" class="${navActive(h)?'active':''}">${mobileIcon(i)}<small>${l}</small></a>`).join('')}</nav>`;
}

function updateNotificationBadges(){document.querySelectorAll('[data-notification-badge]').forEach(b=>{b.textContent=fmt(state.notificationUnread);b.hidden=!state.notificationUnread;});}

function route(){
  const p=path();
  if(state.slideTimer){clearInterval(state.slideTimer); state.slideTimer=null;}
  if(state.messagePoll&&p!=='/nachrichten'){clearInterval(state.messagePoll);state.messagePoll=null;}
  let renderer;
  if(p.startsWith('/mention/')) renderer=()=>renderMentionResolver(decodeURIComponent(p.split('/')[2]||''));
  else if(p.startsWith('/news/')) renderer=()=>renderNewsArticleShell(decodeURIComponent(p.split('/')[2]||''));
  else if(p.startsWith('/spieler/')) renderer=()=>renderPlayerProfileShell(decodeURIComponent(p.split('/')[2]||''));
  else if(p.startsWith('/club/')) renderer=()=>renderClubProfileShell(decodeURIComponent(p.split('/')[2]||''));
  else renderer=(routes.find(([r])=>r===p)||routes[0])[1];
  app.innerHTML = layout(renderer());
  bindGlobal();
  bindEditMode();
  bindPage(p);
}
function bindGlobal(){
  document.querySelector('[data-action="logout"]')?.addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{} state.me=null; toast('Du bist abgemeldet.'); goto('/');});
  document.querySelector('#mobileMenu')?.addEventListener('click',()=>document.querySelector('#mobileDrawer')?.classList.toggle('open'));
  document.querySelector('[data-mobile-close]')?.addEventListener('click',()=>document.querySelector('#mobileDrawer')?.classList.remove('open'));
  document.querySelectorAll('[data-edit-mode-toggle]').forEach(b=>b.addEventListener('click',()=>{state.editMode=!state.editMode;sessionStorage.setItem('epl_edit_mode',state.editMode?'1':'0');route();}));
}


function socialPostCard(post,{compact=false}={}){
  const player=post.author_type!=='club',isAdmin=canModerateViewer(),canSelfDelete=!!(state.me&&((player&&String(post.author_slug||'').toLowerCase()===String(state.me.username||'').toLowerCase())||(!player&&String(post.author_slug||'').toLowerCase()===String(state.me.managed_club_slug||'').toLowerCase())));
  return `<article class="panel social-post ${compact?'compact':''}" data-post-card="${post.id}">
    <div class="social-post-head">
      <a data-link href="/${player?'spieler':'club'}/${esc(post.author_slug)}" class="social-author-avatar"><img src="${authorImage(post)}" alt="">${player?onlineDot(post.author_online):''}</a>
      <div class="social-author-copy"><a data-link href="/${player?'spieler':'club'}/${esc(post.author_slug)}"><strong>${esc(post.author_name)}</strong></a><small>${player?(Number(post.author_online)?'Online':'Offline'):'Club'} • ${formatDateTime(post.created_at)}</small></div>
      <div class="post-tools">${state.me&&!canSelfDelete?`<button type="button" data-report-type="POST" data-report-id="${post.id}">⚑ Melden</button>`:''}${canSelfDelete?`<button type="button" class="danger-link" data-self-delete-post="${post.id}">🗑 Löschen</button>`:''}${isAdmin&&!canSelfDelete?`<button type="button" class="danger-link" data-admin-delete-type="POST" data-admin-delete-id="${post.id}">🛡 Admin löschen</button>`:''}</div>
    </div>
    <p class="social-post-body">${formatMentions(post.body)}</p>
    ${post.media_key?`<img class="social-post-media" src="${assetUrl(post.media_key,'')}" alt="Beitragsbild">`:''}
    ${state.me?.managed_club_slug?`<div class="social-identity"><label>Interagieren als <select data-social-actor><option value="">${esc(state.me.username)}</option><option value="${esc(state.me.managed_club_slug)}">Club (${esc(state.me.managed_club_slug)})</option></select></label></div>`:''}
    <div class="reaction-summary"><span>❤️ ${fmt(post.likes||0)}</span><span>🔥 ${fmt(post.fires||0)}</span><span>👏 ${fmt(post.claps||0)}</span><span>⚽ ${fmt(post.goals||0)}</span><button type="button" data-comments-toggle="${post.id}">💬 ${fmt(post.comments||0)} Kommentare</button></div>
    <div class="reaction-actions">
      <button type="button" data-post-reaction="LIKE" data-post-id="${post.id}">❤️ Gefällt mir</button>
      <button type="button" data-post-reaction="FIRE" data-post-id="${post.id}">🔥</button>
      <button type="button" data-post-reaction="CLAP" data-post-id="${post.id}">👏</button>
      <button type="button" data-post-reaction="GOAL" data-post-id="${post.id}">⚽</button>
      <button type="button" data-comments-toggle="${post.id}">Kommentieren</button>
    </div>
    <div class="post-comments" data-comments-for="${post.id}" hidden></div>
  </article>`;
}
