function openAdminReport(id){const summary=state.admin.reports.find(x=>Number(x.id)===Number(id));const loading=modal(`Meldung #${id}`,`<div class="loading-block">Meldung und gemeldeten Inhalt werden geladen…</div>`);api(`/api/admin/report/${id}`).then(({report,target})=>{const targetHtml=target?`<div class="report-target-preview"><div class="panel-title">GEMELDETER INHALT</div>${target.title?`<h3>${esc(target.title)}</h3>`:''}${target.author?`<p><b>Autor:</b> ${esc(target.author)}</p>`:''}${target.username?`<p><b>Benutzer:</b> ${esc(target.username)}</p>`:''}${target.name?`<p><b>Club:</b> ${esc(target.name)}</p>`:''}${target.body?`<div class="report-content-body">${esc(target.body)}</div>`:''}${target.post_body?`<div class="report-context"><b>Zugehöriger Beitrag:</b><p>${esc(target.post_body)}</p></div>`:''}${target.media_key?`<img src="${assetUrl(target.media_key,'')}" alt="Gemeldetes Bild">`:''}${target.image_key?`<img src="${assetUrl(target.image_key,'')}" alt="News Bild">`:''}<div class="tiny muted">${target.created_at?formatDateTime(target.created_at):''}</div></div>`:`<div class="report-target-preview"><p class="muted">Der gemeldete Inhalt wurde bereits gelöscht oder ist nicht mehr verfügbar.</p></div>`;loading.querySelector('.modal').innerHTML=`<button class="modal-close">×</button><h2>Meldung #${report.id}</h2><div class="report-detail-grid"><section><span class="panel-title">MELDUNG</span><p><b>Melder:</b> ${esc(report.reporter)}</p><p><b>Ziel:</b> ${esc(report.target_type)} #${esc(report.target_id)}</p><p><b>Grund:</b> ${esc(report.reason)}</p><div class="report-content-body">${esc(report.details||'Keine zusätzlichen Details.')}</div><p class="tiny muted">${formatDateTime(report.created_at)} • Status ${esc(report.status)}</p></section>${targetHtml}</div><div class="form-actions"><button class="btn" data-report-reject>ABLEHNEN</button><button class="btn btn-primary" data-report-resolve>ERLEDIGT</button>${['POST','COMMENT','NEWS'].includes(report.target_type)?'<button class="btn danger" data-report-delete>INHALT LÖSCHEN</button>':''}</div>`;loading.querySelector('.modal-close').onclick=()=>loading.remove();loading.querySelector('[data-report-reject]')?.addEventListener('click',async()=>{try{await api('/api/admin/report/resolve',{method:'POST',body:JSON.stringify({reportId:id,status:'REJECTED'})});loading.remove();reloadAdmin()}catch(e){toast(e.message,'error')}});loading.querySelector('[data-report-resolve]')?.addEventListener('click',async()=>{try{await api('/api/admin/report/resolve',{method:'POST',body:JSON.stringify({reportId:id,status:'RESOLVED'})});loading.remove();reloadAdmin()}catch(e){toast(e.message,'error')}});loading.querySelector('[data-report-delete]')?.addEventListener('click',async()=>{if(!confirm('Gemeldeten Inhalt wirklich löschen?'))return;try{await api('/api/admin/content/delete',{method:'POST',body:JSON.stringify({targetType:report.target_type,targetId:report.target_id,reason:`Meldung #${id}: ${report.reason}`})});await api('/api/admin/report/resolve',{method:'POST',body:JSON.stringify({reportId:id,status:'RESOLVED'})});loading.remove();reloadAdmin()}catch(e){toast(e.message,'error')}})}).catch(e=>{loading.remove();toast(e.message,'error')})}
