async function ensureCmsAdminData(){
  if(!state.admin)state.admin={};
  if(!state.admin.cms||!state.admin.cms.slides){state.admin.cms=await api('/api/admin/cms');}
  return state.admin.cms;
}
async function openInlineText(pageKey,contentKey,label,currentValue){
  const m=modal(`Direkt bearbeiten – ${esc(label)}`,`<form><div class="field"><label>${esc(label)}</label><textarea name="value" rows="6">${esc(currentValue||'')}</textarea></div><div class="form-actions"><button class="btn btn-primary">SPEICHERN</button></div></form>`);
  m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/cms/text/save',{method:'POST',body:JSON.stringify({pageKey,contentKey,label,value:e.target.value.value,sortOrder:0})});await refreshCms();m.remove();toast('Text gespeichert.');route();}catch(err){toast(err.message,'error')}};
}
async function openInlinePage(key){await ensureCmsAdminData();const x=(state.cms.pages||[]).find(p=>p.page_key===key)||{page_key:key};const m=modal(`Seite direkt bearbeiten – /${esc(key)}`,`<form><div class="form-grid"><div class="field"><label>Eyebrow</label><input name="eyebrow" value="${esc(x.eyebrow||'')}"></div><div class="field"><label>Titel</label><input name="title" value="${esc(x.title||'')}"></div><div class="field full"><label>Untertitel</label><textarea name="subtitle" rows="4">${esc(x.subtitle||'')}</textarea></div></div><div class="form-actions"><button class="btn btn-primary">SPEICHERN</button></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.pageKey=key;try{await api('/api/admin/cms/page/save',{method:'POST',body:JSON.stringify(d)});await refreshCms();m.remove();toast('Seite gespeichert.');route();}catch(err){toast(err.message,'error')}};}
function bindEditMode(){
  if(!state.editMode)return;
  const root=document.querySelector('main.page');if(!root)return;
  root.querySelectorAll('[data-inline-slide]').forEach(el=>el.addEventListener('click',async e=>{if(e.target.closest('a,button'))return;e.preventDefault();e.stopPropagation();try{await ensureCmsAdminData();openCmsSlide(Number(el.dataset.inlineSlide));}catch(err){toast(err.message,'error')}}));
  root.querySelectorAll('[data-inline-block]').forEach(el=>el.addEventListener('click',async e=>{if(e.target.closest('a,button'))return;e.preventDefault();e.stopPropagation();try{await ensureCmsAdminData();openCmsBlock(Number(el.dataset.inlineBlock));}catch(err){toast(err.message,'error')}}));
  root.querySelectorAll('[data-inline-page]').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('a,button'))return;e.preventDefault();e.stopPropagation();openInlinePage(el.dataset.inlinePage);}));
  root.querySelectorAll('[data-inline-entry]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const [pageKey,contentKey,label]=el.dataset.inlineEntry.split('|');openInlineText(pageKey,contentKey,label,el.textContent.replace(/^⚑\s*/,''));}));
}

function openReportModal(type,id){if(!state.me)return goto('/login');const m=modal('Inhalt melden',`<form><div class="field"><label>Grund</label><select name="reason"><option>Spam</option><option>Beleidigung / Belästigung</option><option>Unangemessener Inhalt</option><option>Fake / Täuschung</option><option>Sonstiges</option></select></div><div class="field" style="margin-top:10px"><label>Details (optional)</label><textarea name="details" rows="4" maxlength="800"></textarea></div><div class="form-actions"><button class="btn btn-primary">MELDUNG SENDEN</button></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/reports',{method:'POST',body:JSON.stringify({targetType:type,targetId:id,reason:e.target.reason.value,details:e.target.details.value})});m.remove();toast('Danke. Die Meldung wurde an die Moderation gesendet.')}catch(err){toast(err.message,'error')}}}

